"""Reset-only lessons whose dynamic handoff is generated by the native prefix.

The bank contains geometric *starts*, not recorded dynamic handoff states. Every
selected episode still runs the original physical controller, sensor readiness
and 200 ms blend. This sampler never writes physics, FSM state or success flags.
"""
from __future__ import annotations

from copy import deepcopy
import math

import torch

from .recovery_curriculum import RecoveryResetCurriculum, pose_probabilities, validate_pose_curriculum


SCHEMA = "v6-recovery-native-prefix-curriculum-v1"
LESSONS = ("prefix_stand", "prefix_release", "original_chain")
GOAL_BRIDGE = "native-original-followup-after-stable-gate-v1"


def prefix_settings(origin_actor_update=2294, *, bridge_original_goals=False):
    """A frozen monotone actor clock; probabilities are proposals, not passes."""
    if type(bridge_original_goals) is not bool:
        raise ValueError("Recovery goal bridge requires an explicit boolean authoring choice")
    result = dict(schema=SCHEMA, enabled=True, clock="domain_actor_updates",
        origin_actor_update=origin_actor_update, sampling="episode_reset_only",
        interpolation="linear", handoff_state="generated_by_continuous_native_prefix",
        state_source="authenticated_geometry_start_not_dynamic_snapshot",
        blend_seconds=.2, stable_seconds=1.,
        keyframes=[dict(actor_update=u, probabilities=dict(zip(LESSONS, p)))
            for u, p in ((0, (.95, .05, 0.)), (1000, (.65, .30, .05)),
                         (3000, (.35, .40, .25)), (6000, (.20, .30, .50)))],
        release_schedule=[dict(actor_update=u, seconds=s)
            for u, s in ((0, .03), (3000, .2))],
        profile_sets={
            "flat": dict(terrain="flat", required_platform_height_m=0.,
                easy=["upright"], medium=["upright_release", "crouched_release",
                    "pitch_forward_45", "pitch_backward_45"]),
            "step200": dict(terrain="step_up", required_platform_height_m=.2,
                easy=["step200_upright_top"], medium=["step200_upright_top"]),
            **{f"stairs_{level}": dict(terrain="stairs", required_platform_height_m=height,
                easy=[f"double_step_{level}_upright_top"],
                medium=[f"double_step_{level}_upright_top"])
                for level, height in (("first", .2), ("second", .45))}})
    if bridge_original_goals:
        result["goal_bridge"] = GOAL_BRIDGE
    return result


def _pose_settings(settings):
    return dict(schema="v6-recovery-pose-curriculum-v1", enabled=True,
        clock=settings["clock"], origin_actor_update=settings["origin_actor_update"],
        sampling=settings["sampling"], interpolation=settings["interpolation"],
        keyframes=[dict(actor_update=p["actor_update"], probabilities=dict(zip(
            ("easy", "medium", "hard"), [p["probabilities"][name] for name in LESSONS])))
            for p in settings["keyframes"]], profile_sets=deepcopy(settings["profile_sets"]))


def validate_prefix_curriculum(settings):
    expected = prefix_settings()
    if (not isinstance(settings, dict)
            or settings.keys() not in (expected.keys(), expected.keys() | {"goal_bridge"})):
        raise ValueError("Recovery prefix curriculum requires its complete explicit schema")
    if "goal_bridge" in settings and settings["goal_bridge"] != GOAL_BRIDGE:
        raise ValueError("Unsupported recovery prefix goal bridge")
    if settings["enabled"] is not True:
        raise ValueError("Recovery prefix must explicitly enable its frozen native sampler")
    for key in ("schema", "enabled", "clock", "sampling", "interpolation", "handoff_state",
                "state_source", "blend_seconds", "stable_seconds"):
        if settings[key] != expected[key]:
            raise ValueError("Unsupported recovery prefix " + key)
    points = settings["keyframes"]
    if not isinstance(points, list) or not points:
        raise ValueError("Recovery prefix needs probability keyframes")
    for point in points:
        if (not isinstance(point, dict) or point.keys() != {"actor_update", "probabilities"}
                or not isinstance(point["probabilities"], dict)
                or point["probabilities"].keys() != set(LESSONS)):
            raise ValueError("Recovery prefix probability lesson fields differ")
    validate_pose_curriculum(_pose_settings(settings))
    # Increasing cumulative difficulty makes time progression auditable. L1/L2
    # still retain a positive floor after the original-chain share increases.
    for left, right in zip(points, points[1:]):
        a, b = left["probabilities"], right["probabilities"]
        if b["prefix_stand"] > a["prefix_stand"] or b["original_chain"] < a["original_chain"]:
            raise ValueError("Recovery prefix difficulty must advance monotonically")
    if points[-1]["probabilities"]["prefix_stand"] <= 0 or points[-1]["probabilities"]["prefix_release"] <= 0:
        raise ValueError("Recovery prefix lessons need permanent rehearsal floors")
    previous_update, previous_seconds = -1, -1.
    schedule = settings["release_schedule"]
    if not isinstance(schedule, list) or not schedule:
        raise ValueError("Recovery prefix needs a finite passive release schedule")
    for point in schedule:
        if not isinstance(point, dict) or point.keys() != {"actor_update", "seconds"}:
            raise ValueError("Invalid recovery prefix release keyframe")
        update, seconds = point["actor_update"], point["seconds"]
        if (type(update) is not int or update <= previous_update
                or type(seconds) not in (int, float) or not math.isfinite(seconds)
                or not previous_seconds <= seconds <= .2 or seconds < 0
                or abs(seconds / .005 - round(seconds / .005)) > 1e-7):
            raise ValueError("Recovery prefix release schedule must rise to at most 0.2 s")
        previous_update, previous_seconds = update, seconds
    if schedule[0]["actor_update"] != 0:
        raise ValueError("Recovery prefix release clock must start at relative zero")


def release_seconds(settings, actor_update):
    if type(actor_update) is not int or actor_update < 0:
        raise ValueError("Recovery prefix needs a nonnegative domain actor clock")
    relative = max(0, actor_update - settings["origin_actor_update"])
    points = settings["release_schedule"]
    value = points[-1]["seconds"]
    for left, right in zip(points, points[1:]):
        if relative < right["actor_update"]:
            alpha = (relative - left["actor_update"]) / (right["actor_update"] - left["actor_update"])
            value = (1 - alpha) * left["seconds"] + alpha * right["seconds"]
            break
    # The initial zero-torque ownership window ends on a real 200 Hz tick.
    return round(value / .005) * .005


class RecoveryPrefixCurriculum:
    """Reuse the authenticated geometric sampler and native controller exactly."""
    def __init__(self, env, table, settings):
        validate_prefix_curriculum(settings)
        self.env, self.settings = env, deepcopy(settings)
        self._sampler = RecoveryResetCurriculum(env, table, _pose_settings(settings))
        n, device = env.num_envs, env.device
        self.original_followup = torch.tensor([env.skills.specs.get(group, {}).get(
            "recovery_followup_command", [0., 0., .305]) for group in env.scene_groups], device=device)
        self.selected_followup = self.original_followup.clone()
        self.selected_release = torch.zeros(n, device=device)
        self.outcome_recorded = torch.zeros(n, dtype=torch.bool, device=device)
        self.outcome_counts = torch.zeros(3, 4, dtype=torch.long, device=device)

    def __getattr__(self, name):
        # Public pose banks keep the existing initial-state adapter unchanged.
        if name.startswith("_"):
            raise AttributeError(name)
        return getattr(self._sampler, name)

    @property
    def full_chain_mask(self):
        """Only episodes retaining their original start count as original chains."""
        return self.enabled & (self.level_ids == 2)

    def reset(self, ids, actor_update):
        ids = torch.as_tensor(ids, dtype=torch.long, device=self.env.device)
        choices = self._sampler.reset(ids, actor_update)
        active = choices >= 0
        lanes, chosen = ids[active], choices[active]
        if not len(lanes):
            return choices
        levels = self.level_ids[lanes]
        self.selected_followup[lanes] = self.original_followup[lanes]
        # The existing adapter keeps visible motion zero until its native
        # continuous stability gate releases. An explicit bridge retains the
        # original goal for the same subsequent 1 s physical tracking outcome.
        # Easy-born success remains a prefix lesson, never original-chain credit.
        if self.settings.get("goal_bridge") != GOAL_BRIDGE:
            self.selected_followup[lanes[levels == 0], :2] = 0.
        self.selected_release[lanes] = self.initial_release_bank[chosen]
        self.selected_release[lanes[levels == 0]] = 0.
        self.selected_release[lanes[levels == 1]] = release_seconds(self.settings, actor_update)
        self.outcome_recorded[lanes] = False
        return choices

    def apply_lesson(self, recovery, lanes):
        """Update only reset-local command/release buffers, never physical state."""
        recovery.initial_release[lanes] = self.selected_release[lanes]
        recovery.followup_command[lanes] = self.selected_followup[lanes]

    def record_outcomes(self, done, success, terminated, timeouts):
        """Count producer outcomes before auto-reset, once per real episode."""
        if any(value.shape != self.enabled.shape or value.dtype != torch.bool
               for value in (done, success, terminated, timeouts)):
            raise ValueError("Recovery prefix outcomes need per-lane boolean producer flags")
        selected = done & self.enabled & ~self.outcome_recorded
        for level in range(3):
            members = selected & (self.level_ids == level)
            self.outcome_counts[level] += torch.stack((members.sum(),
                (members & success & ~terminated).sum(), (members & terminated).sum(),
                (members & timeouts & ~terminated & ~success).sum()))
        self.outcome_recorded |= selected

    def metrics(self, actor_update):
        probabilities = pose_probabilities(self._sampler.settings, actor_update)
        result = {"/recovery/lesson/relative_actor_updates": float(max(
            0, actor_update - self.settings["origin_actor_update"])),
            "/recovery/lesson/release_seconds": release_seconds(self.settings, actor_update)}
        for index, lesson in enumerate(LESSONS):
            prefix = "/recovery/lesson/" + lesson + "/"
            result[prefix + "probability"] = probabilities[index]
            result[prefix + "population"] = (self.enabled & (self.level_ids == index)).sum()
            result[prefix + "resets"] = self.level_reset_counts[index].clone()
            for column, name in enumerate(("ended", "successes", "failures", "collection_timeouts")):
                result[prefix + name] = self.outcome_counts[index, column].clone()
        return result

    def lesson_metrics(self, true_success):
        """Current populations are explicit; zero population has zero credit."""
        if true_success.shape != self.enabled.shape or true_success.dtype != torch.bool:
            raise ValueError("Recovery prefix success must be the producer's boolean truth")
        result = {}
        for index, lesson in enumerate(LESSONS):
            members = self.enabled & (self.level_ids == index)
            count = members.sum()
            result["/recovery/lesson/" + lesson + "/population"] = count
            result["/recovery/lesson/" + lesson + "/success_fraction"] = (
                (members & true_success).sum() / count.clamp_min(1))
        members = self.full_chain_mask
        result["/recovery/full_chain_population"] = members.sum()
        result["/recovery/full_chain_success"] = (
            (members & true_success).sum() / members.sum().clamp_min(1))
        return result

    def rollout_outcome_metrics(self):
        """Exact episode counters at rollout end, never frame-averaged rates.

        The counts are local to this worker. Difference the counters of two
        endpoints in the same worker to measure a window; a population or an
        instantaneous success fraction is not an ended-episode denominator.
        """
        counts = self.outcome_counts.detach().cpu().tolist()
        result = {}
        for lesson, (ended, successes, failures, timeouts) in zip(LESSONS, counts):
            prefix = "RecoveryOutcomes/" + lesson + "/"
            result.update({prefix + name: value for name, value in (
                ("ended", ended), ("successes", successes), ("failures", failures),
                ("collection_timeouts", timeouts), ("has_completed_episode", int(ended > 0)))})
            if ended:
                result[prefix + "cumulative_success_fraction"] = successes / ended
        return result

    def diagnostics(self):
        return {**self._sampler.diagnostics(),
            "recovery_prefix_lesson_id": self.level_ids.clone(),
            "recovery_prefix_lesson": self.enabled & (self.level_ids >= 0) & (self.level_ids < 2),
            "recovery_original_chain": self.full_chain_mask.clone(),
            "recovery_prefix_release_s": self.selected_release.clone()}

    def runtime_state(self):
        return runtime_expectation(self.settings, enabled=True)


def runtime_expectation(settings, *, enabled):
    validate_prefix_curriculum(settings)
    return dict(enabled=bool(enabled), settings=deepcopy(settings),
        dynamic_handoff_source="continuous_native_prefix_no_mid_episode_state_writes",
        imported_dynamic_bank=False, original_outcome_gates_preserved=True,
        script_and_blend_excluded_from_ppo=True, lesson_and_original_chain_counters_separate=True)
